UPDATE TB_USAU001
   SET PW_FAIL_CNT = #{user.pwFailCount}
	  ,USER_STAT = #{user.userStatus}
	  ,LST_LOGIN_DT = #{user.lastLoginDate}
 WHERE LOGIN_ID = #{user.loginId}

UPDATE TB_USAU001
   SET LOGIN_ID = #{user.loginId}
   	  ,USER_SALT = #{user.salt}
   	  ,USER_PWD = #{user.userPwd}
   	  ,USER_STAT = #{user.userStatus}
   	  ,PW_UPD_DT = #{user.pwUpdateDate}
   	  ,PW_EXP_DT = #{user.pwExpireDate}
   	  ,PW_FAIL_CNT = #{user.pwFailCount}
   	  ,PW_INIT_YN = #{user.pwInitYn}
   	  ,UPD_DT= #{user.writer.updateDate}
   	  ,UPD_ID= #{user.writer.updUserId}
 WHERE USER_ID = #{user.userId}
